    "summary": "Docker daemon stopped responding, causing queue-master to fail to launch worker containers."
  },
  "confidence": "medium",
  "causal_chain": [
    {
      "claim": "Queue-master repeatedly encounters AFUNIXSocketException: No such file or directory when trying to connect to Docker's Unix socket (/var/run/docker.sock).",
      "status": "confirmed",
      "cites": [
        "queue-master-L00003",
        "queue-master-L00009"
      ]
    },
    {
      "claim": "This prevents queue-master from launching or removing worker containers, as shown by DockerSpawner errors.",
      "status": "confirmed",
      "cites": [
        "queue-master-L00009"
      ]
    },
    {
      "claim": "As a result, background job processing that depends on these workers is impaired.",
      "status": "uncertain",
      "cites": [
        "queue-master-L00009"
      ]
    },
    {
      "claim": "Impaired background processing leads to increased latency or error rates in user‑facing services (gateway, orders, inventory, payments).",
      "status": "uncertain",
      "cites": [
        "carts-L00003"
      ]
    }
  ],
  "alternatives": [
    {
      "category": "config_regression",
      "service": "queue-master",
      "why_less_likely": "The error persists over a long time window with no configuration change recorded, and the DockerSpawner error references the standard socket path, not a misconfigured one.",
      "cites": [
        "queue-master-L00009",
        "queue-master-L0015f"
      ]
    },
    {
      "category": "capacity_saturation",
      "service": "docker-daemon",
      "why_less_likely": "Errors are \"No such file or directory\" (socket missing) rather than connection refused or timeout, indicating the socket file does not exist, not that the daemon is overloaded.",
